insert into public.themes (slug, name, tokens, is_builtin, sort_order) values ('zamonaviy', '{"uz": "Zamonaviy", "ru": "Современная", "en": "Modern"}'::jsonb, '{"colors": {"bg": "#ffffff", "surface": "#f7f2ec", "text": "#1d1814", "muted": "#7c7169", "primary": "#6e533f", "accent": "#b89474", "heroBg": "#8d7360", "heroBg2": "#4f3a2c", "heroText": "#f6eee5", "dark": "#4a3628"}, "fonts": {"heading": "Playfair Display", "body": "Montserrat"}, "radius": 18, "pattern": "none", "fabric": "silk", "mannequin": "linen", "dark": false}'::jsonb, true, 1) on conflict (slug) do update set name = excluded.name, tokens = excluded.tokens;
