insert into public.settings (key, value) values ('general', '{"site_name": "Maison Shaydo", "logo_url": "", "tagline": {"uz": "Tikuvchi-dizayner portfoliosi", "ru": "Портфолио дизайнера одежды", "en": "Fashion designer portfolio"}, "seo_description": {"uz": "Tikuvchi-dizayner loyihalari, ilmiy ishlari va yutuqlari", "ru": "Проекты, научные работы и достижения дизайнера одежды", "en": "Projects, research and achievements of a fashion designer"}, "footer_text": {"uz": "Har bir libos — o‘z egasining hikoyasi.", "ru": "Каждое изделие — история своего владельца.", "en": "Every garment tells its owner''s story."}}'::jsonb) on conflict (key) do nothing;
insert into public.settings (key, value) values ('hero', '{"mode": "3d", "image_url": "", "word": {"uz": "SHAYDO", "ru": "SHAYDO", "en": "SHAYDO"}, "eyebrow": {"uz": "Tikuvchi-dizayner", "ru": "Дизайнер одежды", "en": "Fashion designer"}, "side_text": {"uz": "Libos — so‘zsiz aytilgan hikoya", "ru": "Одежда — история без слов", "en": "Clothing is a story told without words"}}'::jsonb) on conflict (key) do nothing;
insert into public.settings (key, value) values ('home', '{"categories_label": {"uz": "Toifalar bo‘yicha", "ru": "По категориям", "en": "Shop by category"}, "categories_title": {"uz": "O‘z uslubingizni toping", "ru": "Найдите свой стиль", "en": "Find your perfect style"}, "categories_text": {"uz": "Har bir kayfiyat, lahza va marosim uchun to‘plamlar", "ru": "Коллекции для любого настроения, момента и события", "en": "Curated collections for every mood, moment and occasion"}, "welcome_label": {"uz": "Xush kelibsiz", "ru": "Добро пожаловать", "en": "Welcome to"}, "welcome_title": {"uz": "Libosdan ko‘proq", "ru": "Больше, чем одежда", "en": "More than fashion"}, "welcome_text": {"uz": "Har bir loyiha mato tanlashdan boshlanadi. Milliy an’ana va zamonaviy bichim uyg‘unligida yaratilgan liboslar bilan tanishing.", "ru": "Каждый проект начинается с выбора ткани. Познакомьтесь с изделиями, в которых национальные традиции сочетаются с современным кроем.", "en": "Every project begins with choosing the fabric. Discover garments where national tradition meets contemporary tailoring."}, "welcome_image": "/assets/img/demo/atelier.svg"}'::jsonb) on conflict (key) do nothing;
insert into public.settings (key, value) values ('about', '{"name": {"uz": "Dizayner ismi", "ru": "Имя дизайнера", "en": "Designer name"}, "role": {"uz": "Tikuvchi-dizayner", "ru": "Дизайнер-модельер", "en": "Fashion designer & tailor"}, "quote": {"uz": "Har bir libosda milliy an’ana va zamonaviy nafosatni uyg‘unlashtiraman.", "ru": "В каждом изделии я соединяю национальные традиции и современную элегантность.", "en": "In every garment I blend national tradition with modern elegance."}, "bio": {"uz": "Milliy matolar va zamonaviy bichim uyg‘unligida ishlaydigan tikuvchi-dizayner. Har bir loyiha mato tanlashdan boshlanadi: atlas, adras, ipak va baxmalning tabiiy go‘zalligini zamonaviy siluetlarda ochib berish asosiy maqsad.\n\nIlmiy izlanishlar milliy kiyim an’analarini o‘rganish va ularni bugungi moda tiliga moslashtirishga qaratilgan.", "ru": "Дизайнер-модельер, работающий на стыке национальных тканей и современного кроя. Каждый проект начинается с выбора ткани: главная цель — раскрыть природную красоту атласа, адраса, шёлка и бархата в современных силуэтах.\n\nНаучные исследования посвящены изучению национальных традиций одежды и их адаптации к языку современной моды.", "en": "A fashion designer and tailor working where national fabrics meet contemporary cut. Every project begins with the fabric: the aim is to reveal the natural beauty of atlas, adras, silk and velvet in modern silhouettes.\n\nResearch focuses on studying national clothing traditions and adapting them to today''s fashion language."}, "photo_url": "/assets/img/demo/portrait.svg", "experience_years": 8, "skills": [{"uz": "Milliy liboslar", "ru": "Национальная одежда", "en": "National wear"}, {"uz": "Bichish va modellashtirish", "ru": "Конструирование и моделирование", "en": "Pattern making"}, {"uz": "Kechki liboslar", "ru": "Вечерние платья", "en": "Evening wear"}, {"uz": "Mato tanlash", "ru": "Подбор тканей", "en": "Fabric selection"}, {"uz": "Qo‘lda kashta", "ru": "Ручная вышивка", "en": "Hand embroidery"}], "timeline": [{"year": "2016", "title": {"uz": "Kasbiy ta’lim", "ru": "Профессиональное образование", "en": "Professional education"}, "text": {"uz": "Tikuvchilik va kiyim dizayni yo‘nalishida ta’lim.", "ru": "Обучение по направлению швейное дело и дизайн одежды.", "en": "Studies in tailoring and fashion design."}}, {"year": "2019", "title": {"uz": "Shaxsiy atelye", "ru": "Собственное ателье", "en": "Own atelier"}, "text": {"uz": "Buyurtma asosida liboslar tikish va birinchi kolleksiya.", "ru": "Пошив на заказ и первая коллекция.", "en": "Made-to-measure tailoring and the first collection."}}, {"year": "2024", "title": {"uz": "Ilmiy faoliyat", "ru": "Научная деятельность", "en": "Research"}, "text": {"uz": "Milliy matolarni zamonaviy dizaynda qo‘llash bo‘yicha izlanishlar.", "ru": "Исследования применения национальных тканей в современном дизайне.", "en": "Research on using national fabrics in contemporary design."}}]}'::jsonb) on conflict (key) do nothing;
insert into public.settings (key, value) values ('contact', '{"phone": "+998 90 000 00 00", "email": "", "address": {"uz": "Toshkent, O‘zbekiston", "ru": "Ташкент, Узбекистан", "en": "Tashkent, Uzbekistan"}, "hours": {"uz": "Du–Sh: 9:00–19:00", "ru": "Пн–Сб: 9:00–19:00", "en": "Mon–Sat: 9:00–19:00"}, "instagram": "", "telegram": "", "facebook": "", "youtube": "", "map_embed": ""}'::jsonb) on conflict (key) do nothing;
insert into public.settings (key, value) values ('gown', '{"silhouette": "aline", "neckline": "illusion", "sleeves": "long", "fabric": "lace", "color": "#efe6d8", "lace": "#fffdf8", "trim": "none", "scallop": true, "spread": 100, "train": 40, "mannequin": "linen", "finial": "silver", "sparkle": false, "motion": true}'::jsonb) on conflict (key) do nothing;
