insert into public.projects (slug, title, description, fabric, fabric_image_url, year, category_id, cover_url, is_featured, sort_order) select 'atlas-jilosi', '{"uz": "Atlas jilosi", "ru": "Сияние атласа", "en": "Atlas Glow"}'::jsonb, '{"uz": "Marg‘ilon atlasidan tikilgan uzun ko‘ylak. Yoqa va etak zarrin hoshiya bilan bezatilgan, bichimi esa zamonaviy A-siluetda.", "ru": "Длинное платье из маргиланского атласа. Ворот и подол украшены золотой каймой, крой — современный А-силуэт.", "en": "A long dress in Margilan atlas silk. The collar and hem carry a golden trim, cut in a modern A-line silhouette."}'::jsonb, '{"uz": "Atlas (ipak)", "ru": "Атлас (шёлк)", "en": "Atlas (silk)"}'::jsonb, '/assets/img/demo/fabric-atlas.svg', 2025, c.id, '/assets/img/demo/p-atlas.svg', true, 1 from public.categories c where c.slug = 'milliy' on conflict (slug) do nothing;
insert into public.project_images (project_id, url, original_url, mode, sort_order) select p.id, '/assets/img/demo/p-atlas.svg', '/assets/img/demo/p-atlas.svg', 'original', 0 from public.projects p where p.slug = 'atlas-jilosi' and not exists (select 1 from public.project_images pi where pi.project_id = p.id and pi.url = '/assets/img/demo/p-atlas.svg');
insert into public.project_images (project_id, url, original_url, mode, sort_order) select p.id, '/assets/img/demo/p-atlas-2.svg', '/assets/img/demo/p-atlas-2.svg', 'original', 1 from public.projects p where p.slug = 'atlas-jilosi' and not exists (select 1 from public.project_images pi where pi.project_id = p.id and pi.url = '/assets/img/demo/p-atlas-2.svg');
insert into public.projects (slug, title, description, fabric, fabric_image_url, year, category_id, cover_url, is_featured, sort_order) select 'tungi-nafosat', '{"uz": "Tungi nafosat", "ru": "Ночная элегантность", "en": "Evening Grace"}'::jsonb, '{"uz": "Tabiiy ipakdan kechki ko‘ylak: belga yopishgan ustki qism va yengil to‘lqinlanuvchi keng etak.", "ru": "Вечернее платье из натурального шёлка: облегающий лиф и лёгкая струящаяся юбка.", "en": "An evening gown in natural silk: a fitted bodice and a light, flowing skirt."}'::jsonb, '{"uz": "Tabiiy ipak", "ru": "Натуральный шёлк", "en": "Natural silk"}'::jsonb, '/assets/img/demo/fabric-silk.svg', 2025, c.id, '/assets/img/demo/p-evening.svg', true, 2 from public.categories c where c.slug = 'kechki' on conflict (slug) do nothing;
insert into public.project_images (project_id, url, original_url, mode, sort_order) select p.id, '/assets/img/demo/p-evening.svg', '/assets/img/demo/p-evening.svg', 'original', 0 from public.projects p where p.slug = 'tungi-nafosat' and not exists (select 1 from public.project_images pi where pi.project_id = p.id and pi.url = '/assets/img/demo/p-evening.svg');
insert into public.project_images (project_id, url, original_url, mode, sort_order) select p.id, '/assets/img/demo/p-evening-2.svg', '/assets/img/demo/p-evening-2.svg', 'original', 1 from public.projects p where p.slug = 'tungi-nafosat' and not exists (select 1 from public.project_images pi where pi.project_id = p.id and pi.url = '/assets/img/demo/p-evening-2.svg');
insert into public.projects (slug, title, description, fabric, fabric_image_url, year, category_id, cover_url, is_featured, sort_order) select 'adras-chopon', '{"uz": "Adras chopon", "ru": "Чапан из адраса", "en": "Adras Chapan"}'::jsonb, '{"uz": "An’anaviy chopon bichimi zamonaviy uzunlik va ingichka belbog‘ bilan qayta talqin qilingan.", "ru": "Традиционный крой чапана, переосмысленный в современной длине с тонким поясом.", "en": "A traditional chapan cut reinterpreted with a modern length and a slim belt."}'::jsonb, '{"uz": "Adras", "ru": "Адрас", "en": "Adras"}'::jsonb, '/assets/img/demo/fabric-adras.svg', 2024, c.id, '/assets/img/demo/p-chopon.svg', true, 3 from public.categories c where c.slug = 'milliy' on conflict (slug) do nothing;
