insert into public.projects (slug, title, description, fabric, fabric_image_url, year, category_id, cover_url, is_featured, sort_order) select 'baxmal-kecha', '{"uz": "Baxmal kecha", "ru": "Бархатная ночь", "en": "Velvet Night"}'::jsonb, '{"uz": "“Suv parisi” siluetidagi baxmal ko‘ylak: qomatni ta’kidlaydi va pastda keng ochiladi.", "ru": "Бархатное платье силуэта «русалка»: подчёркивает фигуру и расширяется книзу.", "en": "A mermaid-silhouette velvet gown that follows the figure and flares at the hem."}'::jsonb, '{"uz": "Baxmal", "ru": "Бархат", "en": "Velvet"}'::jsonb, '/assets/img/demo/fabric-velvet.svg', 2024, c.id, '/assets/img/demo/p-velvet.svg', true, 4 from public.categories c where c.slug = 'kechki' on conflict (slug) do nothing;
