insert into public.research (title, venue, summary, year, link_url, sort_order) values ('{"uz": "Ilmiy maqola nomi (namuna)", "ru": "Название научной статьи (образец)", "en": "Research paper title (sample)"}'::jsonb, '{"uz": "Jurnal yoki konferensiya nomi", "ru": "Название журнала или конференции", "en": "Journal or conference name"}'::jsonb, '{"uz": "Bu namuna yozuv. Admin paneldagi “Ilmiy ishlar” bo‘limidan haqiqiy ilmiy ishingizni qo‘shing va PDF faylini yuklang.", "ru": "Это пример записи. Добавьте реальную научную работу и PDF-файл в разделе «Научные работы» админ-панели.", "en": "This is a sample entry. Add your real research and upload its PDF in the “Research” section of the admin panel."}'::jsonb, 2025, '', 1);
insert into public.research (title, venue, summary, year, link_url, sort_order) values ('{"uz": "Konferensiya tezisi nomi (namuna)", "ru": "Название тезисов конференции (образец)", "en": "Conference abstract title (sample)"}'::jsonb, '{"uz": "Konferensiya nomi", "ru": "Название конференции", "en": "Conference name"}'::jsonb, '{"uz": "Qisqa izoh: tadqiqot mavzusi, maqsadi va asosiy natijalari.", "ru": "Краткое описание: тема, цель и основные результаты исследования.", "en": "Short summary: the topic, aim and main results of the study."}'::jsonb, 2024, '', 2);
